{
  "name": "@jsonzx/opencode-multimodal-attachments",
  "version": "0.1.4",
  "description": "Give text-only OpenCode models multimodal attachment analysis through Gemini.",
  "type": "module",
  "main": "./dist/multimodal-attachments.js",
  "types": "./dist/multimodal-attachments.d.ts",
  "exports": {
    ".": {
      "types": "./dist/multimodal-attachments.d.ts",
      "import": "./dist/multimodal-attachments.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "npm run build && node test/import.mjs",
    "prepack": "npm test"
  },
  "keywords": [
	  "opencode",
	  "opencode-plugin",
	  "multimodal",
	  "vision",
	  "attachments",
	  "office"
  ],
  "license": "MIT",
  "dependencies": {
    "fast-xml-parser": "^5.3.6",
    "jszip": "^3.10.1",
    "mammoth": "^1.11.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "typescript": "^5.9.0"
  }
}
